function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(1800, 2000) : int(1, 9);
  const shape = rand();
  const top = large ? 100000 : (rand() < 0.6 ? 5 : 100000);
  const low = top === 100000 && !large && rand() < 0.5 ? 99995 : 1;
  const list = Array.from({ length: n }, () => int(low, top));
  // Some lists are sorted (all kept or almost all removed) to reach the extremes.
  if (shape < 0.2) list.sort((a, b) => a - b);
  else if (shape < 0.4) list.sort((a, b) => b - a);
  else if (shape < 0.5 && large) for (let i = 0; i < n; i++) list[i] = 100000 - Math.floor(i / 3) - int(0, 1) * (i % 5 === 0 ? 1 : 0);
  return [list];
}
